(()=>{'use strict';const D=window.ATLAS_VALIDATION,$=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let family='all';const evidence=ids=>ids.map(id=>{const s=D.sources.find(x=>x.id===id);return '<a href="#source-'+id+'">'+esc(s.kind)+'</a>';}).join(' · ');
$('#families').innerHTML=D.families.map(f=>'<button data-family="'+f.id+'" aria-pressed="false"><b>'+esc(f.title)+'</b><span>'+f.count+' 套 · '+(f.id==='visual'?'表达研究':'任务方向')+'</span></button>').join('');$('#family').insertAdjacentHTML('beforeend',D.families.map(f=>'<option value="'+f.id+'">'+esc(f.title)+'</option>').join(''));
function render(){const q=$('#query').value.trim().toLowerCase(),level=$('#level').value;const found=D.items.filter(x=>(family==='all'||x.family===family)&&(level==='all'||x.level===level)&&[x.title,x.gap,x.test,x.id].join(' ').toLowerCase().includes(q));$('#count').textContent=found.length+' / 60 套 · 源码层审阅 · 本轮浏览器待复测';$('#empty').hidden=found.length>0;$('#items').innerHTML=found.map(x=>'<details id="'+x.id+'"><summary><b>'+esc(x.title)+'</b><span>'+x.level+' · '+D.families.find(f=>f.id===x.family).title+' · 待接入真实场景</span></summary><div class="entry-body"><dl><dt>为什么适用</dt><dd>'+esc(D.families.find(f=>f.id===x.family).goal)+'</dd><dt>当前不足 / 使用边界</dt><dd>'+esc(x.gap)+'</dd><dt>建议这样验收（尚非实测结果）</dt><dd>'+esc(x.test)+'</dd><dt>验证范围</dt><dd>'+esc(x.sourceCheck)+'；'+esc(x.browserCheck)+'；'+esc(x.effectiveness)+'</dd><dt>判断依据</dt><dd>'+evidence(x.evidence)+'</dd></dl><div class="actions"><a href="'+x.file+'" target="_blank" rel="noopener">运行模板 ↗</a><a href="library.html?item='+x.id+'#collection">查看与下载源码 ↗</a></div></div></details>').join('');const f=D.families.find(x=>x.id===family);$('#task-detail').hidden=!f;if(f)$('#task-detail').innerHTML='<h3>'+esc(f.goal)+'</h3><p><strong>已有支撑：</strong>'+f.count+' 套相关机制或流程，可以作为原型起点。</p><p><strong>还缺什么：</strong>'+esc(f.gap)+'</p><p><strong>验收问题：</strong>'+esc(f.acceptance)+'</p><p>'+evidence(f.evidence)+'</p>';document.querySelectorAll('[data-family]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.family===family)));}
$('#families').onclick=e=>{const b=e.target.closest('[data-family]');if(!b)return;family=b.dataset.family;$('#family').value=family;render();};$('#family').onchange=()=>{family=$('#family').value;render();};$('#query').oninput=render;$('#level').onchange=render;$('#clear').onclick=()=>{family='all';$('#family').value='all';$('#level').value='all';$('#query').value='';render();};
$('#fixes').innerHTML=D.fixes.map(x=>'<article class="box"><span class="tag">'+x.priority+'</span><small>源码已修复 · 浏览器待复测</small><h3>'+esc(x.title)+'</h3><p>'+esc(x.change)+'</p><small>'+esc(x.files.join(' · '))+'</small></article>').join('');$('#backlog').innerHTML=D.backlog.map(x=>'<article class="box"><span class="tag">'+x.priority+' / 未完成验收</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.detail)+'</p><p><strong>完成条件：</strong>'+esc(x.test)+'</p></article>').join('');$('#evidence').innerHTML=D.sources.map(s=>'<article class="box" id="source-'+s.id+'"><small>'+esc(s.kind)+' · '+s.checked+'</small><h3><a href="'+s.url+'" target="_blank" rel="noopener">'+esc(s.title)+' ↗</a></h3><p>'+esc(s.note)+'</p></article>').join('');$('#checks').innerHTML='<p>60 个模板入口存在；'+D.checks.scriptCount+' 个内联及共享脚本语法检查；静态引用缺失 '+D.checks.missingRefs.length+' 项，语法错误 '+D.checks.parseErrors.length+' 项。</p><p id="test-result">正在读取隔离逻辑测试记录…</p>';fetch('validation-tests.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(r=>{$('#test-result').textContent=r.passed+' / '+r.total+' 项隔离逻辑测试通过（'+r.environment+'）。'+r.limit;}).catch(()=>{$('#test-result').textContent='测试记录未加载，可直接下载 JSON 查看；这不表示测试通过。';});let printState=[];window.addEventListener('beforeprint',()=>{printState=[...document.querySelectorAll('details')].map(d=>[d,d.open]);printState.forEach(([d])=>d.open=true);});window.addEventListener('afterprint',()=>printState.forEach(([d,open])=>d.open=open));$('#print').onclick=()=>window.print();render();const target=D.items.find(x=>'#'+x.id===location.hash);if(target){const el=document.getElementById(target.id);el.open=true;el.scrollIntoView();}
})();
(()=>{const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('reference-link-check.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(d=>{document.querySelector('#reference-status').textContent=d.total+' 个入口：'+Object.entries(d.counts).map(([k,v])=>v+' 个'+k).join('；')+'。检查于 '+d.date;document.querySelector('#reference-list').innerHTML=d.items.map(x=>'<article class="box"><a href="'+esc(x.url)+'" target="_blank" rel="noopener">'+esc(x.title)+' ↗</a> · '+esc(x.result)+'（'+esc(x.status??'无响应')+'）'+(x.redirected?'<small> · 有跳转，目标见 JSON</small>':'')+'</article>').join('');}).catch(()=>{document.querySelector('#reference-status').textContent='链接记录暂未加载，请下载 JSON 查看。';});})();
